head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16400n";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16400n.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — corpUserTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_disclsEduApctTpCd", fn: function(){ return (((dma_pageContext.get("corpUserTpCd") ?? "") === '61' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '81') ||
                    ((dma_pageContext.get("corpUserTpCd") ?? "") === '62' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '82') ||
                    ((dma_pageContext.get("corpUserTpCd") ?? "") === '63' && (dlt_educationList.getCellData(0, "disclsEduApctTpCd") ?? (() => { throw new Error("unresolved:" + "education.disclsEduApctTpCd"); })()) === '82')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_33", entity: "dlt_educationList", countIds: [], cells: [{ childId: "option_35", fn: function (v, i) { return String(v("disclsEduApplSeq")) + "," + String(v("disclsEduAcptStrtDd")) + "," + String(v("disclsEduAcptEndDd")) + "," + String(v("disclsEduEvtItmExpYn")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("disclsEduCrsNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// [A] 초기 목록 미해결 — jldfil16400n: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_sltEduRnd1_onchange
 * @description slc_sltEduRnd1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_sltEduRnd1_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.getDsclEduRct(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400n.slc_sltEduRnd1_onchange' }); }
};

/**
 * @method
 * @name btn_Submit_onclick
 * @description 「다음」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Submit_onclick = async function(e){
    try {
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16400n.btn_Submit_onclick' }); }
};

/**
 * @method
 * @name btn_Reset_onclick
 * @description 「초기화」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reset_onclick = function(e){
    try {
        scwin.reset()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16400n.btn_Reset_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function () {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: "/support/eduRspn.do",
        ref: "dma_SubmitReq",
        target: "dlt_educationList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function () {
    const form = (document.eduForm || { elements: [] });
    let arr;
    const today = $c.util.getComponent('dma_SubmitReq').get('today');
    let sdate = '';
    let edate = '';
    let disableYn = '';
    const check = $c.util.getComponent('slc_sltEduRnd1').getValue();
    let title = '';
    arr = slc_sltEduRnd1.value.split(",");
    title = $c.util.getComponent('slc_sltEduRnd1').getItemText($c.util.getComponent('slc_sltEduRnd1').getSelectedIndex());
    if (title === '2011년 상장법인 공시담당자 사이버교육') {
        await $c.win.alert("신청인원이 많아 9월15일부로 교육신청을 마감하겠습니다. 2012년에도 강의를 개설할 예정이니 많은 이용바랍니다");
        return;
    }
    if (arr !== "") {
        $c.util.getComponent('dma_SubmitReq').set('disclsEduApplSeq', arr[0]);
        sdate = arr[1];
        edate = arr[2];
        disableYn = arr[3];
        if (today > edate) {
            await $c.win.alert("제출 기간이 지났습니다.");
            return;
        }
        if (today < sdate) {
            await $c.win.alert("아직 제출 기간이 아닙니다.");
            return;
        }
        if (today >= sdate && today <= edate) {
            if ($c.util.getComponent('dma_SubmitReq').get('corpUserTpCd')=== '61') {
                form.action = 'eduRspn.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'educationResponsibilityForm');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                { const __nr = await scwin.tx_fn_Submit(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'educationResponsibilityForm', "disableYn": disableYn }); } };
            } else {
                form.action = 'eduChrg.do';
                $c.util.getComponent('dma_SubmitReq').set('method', 'educationChargeForm');
                $c.util.getComponent('dma_SubmitReq').set('disableYn', disableYn);
                { const __nr = await scwin.tx_fn_Submit(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16403/jldfil16403.xml", { "method": 'educationResponsibilityForm', "disableYn": disableYn }); } };
            }
        }
    } else {
        if (check === "") {
            await $c.win.alert("교육 회차를 선택해 주세요");
            return;
        }
    }
};

/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    const form = (document.eduForm || { elements: [] });
    $c.util.getComponent('dma_SubmitReq').reset();
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    t_dsclEduRct.innerHTML = "";
};

/**
 * @method
 * @name getDsclEduRct
 * @description get Dscl Edu Rct 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getDsclEduRct = function (obj) {
    const slt_edu_rnd = obj.value;
    const t_dsclEduRct = $c.util.getComponent("txt_dsclEduRct");
    const arr = slt_edu_rnd.split(",");
    let sdate;
    let edate;
    if (arr !== "") {
        sdate = arr[1];
        edate = arr[2];
        t_dsclEduRct.innerHTML = "<b>제출 기간 : " + sdate + " ~ " + edate + "</b>";
    } else {
        t_dsclEduRct.innerHTML = "";
    }
};
